Code.Terraform:
```hcl
# Terraform: log AgentCore data events on an actively logging trail
resource "aws_cloudtrail" "example_resource" {
  name           = "example_resource"
  s3_bucket_name = "example_resource"

  advanced_event_selector {
    name = "Management events"
    field_selector {
      field  = "eventCategory"
      equals = ["Management"]
    }
  }

  advanced_event_selector {
    name = "AgentCore Runtime data events"
    field_selector {
      field  = "eventCategory"
      equals = ["Data"]
    }
    field_selector {
      field  = "resources.type"              # CRITICAL: one resources.type per selector
      equals = ["AWS::BedrockAgentCore::Runtime"]
    }
  }

  advanced_event_selector {
    name = "AgentCore Memory data events"
    field_selector {
      field  = "eventCategory"
      equals = ["Data"]
    }
    field_selector {
      field  = "resources.type"
      equals = ["AWS::BedrockAgentCore::Memory"]
    }
  }

  advanced_event_selector {
    name = "AgentCore Gateway data events"
    field_selector {
      field  = "eventCategory"
      equals = ["Data"]
    }
    field_selector {
      field  = "resources.type"
      equals = ["AWS::BedrockAgentCore::Gateway"]
    }
  }
}
```
